_cpp_type_bindings.target:
struct {
    uint8_t  kind;           /* enum guided_cmd_kind */
    uint8_t  priority;       /* 1 = cut off whatever is playing */
    uint8_t  dark;           /* HOLD tick: darker, slower */
    uint8_t  n_clips;
    float    pan;            /* -1 left .. +1 right */
    float    amp;            /* 0..1 */
    uint16_t clips[GUIDED_MAX_CLIPS];      /* enum beacon_clip */
    char     name[BEACON_NAME_LEN];        /* label for BEACON_CLIP_OBJECT_NAME */
}

struct {
    int          law;        /* enum beacon_law */
    int          mode;       /* enum beacon_mode */
    float        d_m;        /* hand-to-target after EMA, < 0 = none */
    float        pan;
    float        tick_hz;    /* 0 = no ticks */
    int          continuous;
    int          n_cmds;
    guided_cmd_t cmds[GUIDED_MAX_CMDS];
}

struct {
    int      metres_enabled; /* spec §11: only after the tape-measure check passes */
    float    hand_conf_min;
    uint64_t hand_stale_ns;  /* hand older than the target's newest box by this = "hand lost" */
    int      orient_pips;    /* ADDITION: pips while turning toward the target (--no-orient-pips) */
}

struct {
    guided_cfg_t    cfg;
    beacon_target_t target;

    /* intents */
    int      seen_intent;
    uint32_t last_utterance_id;
    uint64_t last_intent_t_ns;
    int      stopped;

    /* REJECT: the FIND/GO request we bound from, and which candidates were tried */
    int             have_bind_intent;
    beacon_intent_t bind_intent;
    uint32_t        tried_mask;

    /* REPEAT: last WALK template or NACK clip, replayed as is (§10) */
    int          have_last_say;
    guided_cmd_t last_say;

    /* RETURN */
    int      returning;
    uint32_t ret_start_i, ret_total, ret_k;
    int      ret_refused_said;

    /* REACH */
    int      in_reach;
    int      reach_enter_n;
    int      d_valid;
    float    d_ema;
    float    lat_ema;
    float    amp;
    uint64_t d_t_ns;
    uint64_t next_tick_ns;
    int      tone_on;
    uint64_t tone_since_ns;  /* when the continuous tone started */
    int      found;          /* "found it" said; quiet until the hand moves away */
    int      turning;        /* giving "turn left/right" from the session map */
    uint16_t turn_clip;      /* last turn instruction spoken */
    uint64_t turn_change_ns; /* when a different turn instruction first applied */

    /* WALK speaking rules */
    int      walk_started;   /* full sentence said for this target */
    int      cue_dir;        /* direction last spoken */
    uint16_t cue_dist;       /* distance clip last spoken (0 = none) */
    uint64_t change_ns;      /* when the direction/distance first differed */

    /* turn-toward pips (ADDITION) */
    int      orienting;      /* target off to one side: pips until we face it */
    uint64_t next_pip_ns;
    uint64_t pips_until_ns;  /* pips stop after a few seconds; the next spoken cue restarts them */
    uint64_t last_chime_ns;  /* one chime per ~3 s */
    uint64_t last_landmark_ns; /* "It's next to ..." at most every ~8 s */

    /* WALK and mode bookkeeping */
    uint64_t last_walk_ns;
    int      prev_mode;
    int      lost_said;
    uint64_t last_lost_say_ns; /* "I lost the target": first say immediate, then gap */
}

struct {
    float    scale, pad_x, pad_y;  /* letterbox of full W x H onto net w x h (spec §7) */
    uint32_t net_w, net_h;
}

struct {
    beacon_seq_t seq;
    uint32_t     _pad0;
    uint64_t     frame_id;     /* monotonic */
    uint64_t     t_ns;         /* CLOCK_MONOTONIC at dequeue */
    uint32_t     width, height, stride, frametype;
    uint32_t     bytes_used;
    uint32_t     _pad1;
    uint8_t      pixels[BEACON_FRAME_MAX_BYTES];
}

struct {
    uint32_t            abi;
    uint32_t            newest_slot; /* hint; readers still check each slot's seq */
    beacon_frame_slot_t slot[BEACON_FRAME_SLOTS];
}

struct {
    beacon_seq_t       seq;
    uint32_t           abi;
    uint64_t           frame_id, t_ns;
    uint32_t           w_d, h_d;          /* depth net output, ~210 */
    beacon_letterbox_t depth_affine;      /* CAM_W x CAM_H -> w_d x h_d */
    beacon_letterbox_t yolo_affine;       /* CAM_W x CAM_H -> 320 x 320 */
    float              hand_crop_origin_x, hand_crop_origin_y, hand_crop_scale;
    float              metres[BEACON_DEPTH_MAX_W * BEACON_DEPTH_MAX_H]; /* <= 0 or NaN = invalid */
}

struct {
    float    T_world_from_cam[16]; /* row-major 4x4 */
    uint64_t t_ns;
    uint64_t age_ns;
    uint32_t pose_epoch;           /* bumped on every percept restart */
    uint8_t  valid;
    uint8_t  _pad[3];
}

struct {
    uint32_t id;
    char     name[BEACON_NAME_LEN];
    float    xyz_cam[3];           /* OpenCV camera frame: +X right, +Y down, +Z forward, metres */
    float    xyz_world[3];
    float    bbox_px[4];           /* full-frame pixels: x0, y0, x1, y1 */
    float    conf;
    uint64_t last_seen_ns;         /* capture time of the last box */
    uint64_t frame_id;
    uint32_t pose_epoch;
    uint8_t  in_latest_boxes;      /* 1 iff this name had a box in the cycle that wrote this seq */
    uint8_t  used;                 /* ADDITION: row in use (rows are never deleted when out of view) */
    uint8_t  _pad[2];
}

struct {
    float    T_world_from_cam[16];
    uint64_t t_ns;
}

struct {
    float    xyz_cam[3];
    float    xyz_world[3];
    float    conf;
    uint64_t t_ns;                 /* capture time of its frame */
    uint64_t frame_id;
    uint32_t pose_epoch;           /* ADDITION: spec §7 Range 1 compares hand.pose_epoch */
    uint8_t  valid;                /* ADDITION: 0 = no hand in that frame */
    uint8_t  _pad[3];
}

struct {
    uint64_t hb_percept_ns;
    uint32_t last_yolo_ms, last_depth_ms;
    uint64_t p95_vision_ns;        /* 0 until measured */
}

struct {                   /* written by percept under seq_percept */
    beacon_pose_t           pose;
    beacon_object_t         objects[BEACON_MAX_OBJECTS];
    beacon_crumb_t          crumbs[BEACON_MAX_CRUMBS];
    uint32_t                crumb_i, crumb_n; /* next write index, count */
    beacon_hand_t           hand;
    beacon_percept_health_t health;
}

struct {                   /* written by voiced under seq_voiced */
    uint32_t kind;                 /* enum beacon_intent_kind */
    uint32_t n_candidates;
    char     candidates[BEACON_MAX_CANDIDATES][BEACON_NAME_LEN];
    uint64_t t_ns;
    uint32_t utterance_id;         /* ADDITION: +1 per request so guided sees repeats of the same words */
    uint32_t _pad;
}

struct {
    uint32_t id;
    char     name[BEACON_NAME_LEN];
    float    xyz_cam[3];
    float    xyz_world[3];
    float    conf;
    uint64_t last_seen_ns;
    uint64_t frame_id;
    uint32_t pose_epoch;
    uint8_t  bound;                /* ADDITION: 0 = no target */
    uint8_t  in_latest_boxes;      /* ADDITION: copied at refresh, drives LIVE */
    uint8_t  _pad[2];
}

struct {
    uint32_t law;                  /* enum beacon_law */
    float    d_m;                  /* hand-to-target, < 0 = none */
    float    pan;                  /* -1 left .. +1 right */
    float    tick_hz;              /* 0 = no ticks */
    uint8_t  continuous;           /* continuous tone */
    uint8_t  n_last_clips;
    uint16_t last_clips[12];       /* last spoken clip sequence (enum beacon_clip) */
    uint8_t  _pad[2];
}

struct {
    uint64_t loops;
    uint64_t misses;               /* 16 ms deadlines missed */
    uint64_t worst_late_ns;
    uint64_t p95_late_ns;
}

struct {                   /* written by guided under seq_guided */
    uint64_t                hb_guided_ns;
    beacon_target_t         target;
    beacon_guided_display_t display; /* ADDITION */
    beacon_guided_stats_t   stats;   /* ADDITION */
}

struct {
    uint32_t               abi;
    uint32_t               _pad;
    beacon_seq_t           seq_percept;
    uint32_t               _pad_p;
    beacon_percept_block_t percept;
    beacon_seq_t           seq_voiced;
    uint32_t               _pad_v;
    beacon_intent_t        intent;
    beacon_seq_t           seq_guided;
    uint32_t               _pad_g;
    beacon_guided_block_t  guided;
}
